1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/url"
9		"os/exec"
10		"sort"
11		"strconv"
12		"strings"
13		"time"
14	
15		"charm.land/bubbles/v2/key"
16		tea "charm.land/bubbletea/v2"
17		"charm.land/huh/v2"
18		"charm.land/lipgloss/v2"
19		"github.com/spf13/cobra"
20	
21		"github.com/entireio/cli/cmd/entire/cli/agent"
22		"github.com/entireio/cli/cmd/entire/cli/agent/external"
23		"github.com/entireio/cli/cmd/entire/cli/agent/types"
24		"github.com/entireio/cli/cmd/entire/cli/api"
25		"github.com/entireio/cli/cmd/entire/cli/auth"
26		"github.com/entireio/cli/cmd/entire/cli/gitremote"
27		"github.com/entireio/cli/cmd/entire/cli/palette"
28		"github.com/entireio/cli/cmd/entire/cli/paths"
29		"github.com/entireio/cli/cmd/entire/cli/uiform"
30		"github.com/entireio/cli/internal/coreapi"
31	)
32	
33	const (
34		configureAccessPollInterval = 2 * time.Second
35		configureAccessWaitTimeout  = 5 * time.Minute
36		configureCommitMessage      = "chore: configure entire"
37		configureBranchBase         = "configure-entire"
38		configureSaveDirect         = "direct"
39		configureSaveNewBranch      = "new-branch"
40	)
41	
42	// configureAccessReporter is the small part of the authenticated API used by
43	// onboarding. Keeping it narrow makes the state machine independently testable.
44	type configureAccessReporter interface {
45		ReportEnable(ctx context.Context, remoteURL string) (*api.EnableRepoResponse, error)
46	}
47	
48	// configureFlowDeps contains side effects used by the interactive configure
49	// flow. Tests can replace individual operations without a keyring, browser,
50	// GitHub CLI, or live control plane.
51	type configureFlowDeps struct {
52		resolveAuth  func(context.Context) (statusTarget, error)
53		fetchProfile profileFetcher
54		runLogin     func(context.Context, io.Writer, io.Writer) error
55		accessClient func(context.Context) (configureAccessReporter, error)
56		coreClient   func() (*coreapi.Client, error)
57		openURL      browserOpenFunc
58		githubAdmin  func(context.Context, string, string) (bool, error)
59		now          func() time.Time
60	}
61	
62	func newConfigureFlowDeps(insecure bool) configureFlowDeps {
63		return configureFlowDeps{
64			resolveAuth: func(ctx context.Context) (statusTarget, error) {
65				return resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
66			},
67			fetchProfile: defaultFetchProfile,
68			runLogin: func(ctx context.Context, outW, errW io.Writer) error {
69				cmd := newLoginCmd()
70				cmd.SetContext(ctx)
71				cmd.SetOut(outW)
72				cmd.SetErr(errW)
73				return cmd.RunE(cmd, nil)
74			},
75			accessClient: func(ctx context.Context) (configureAccessReporter, error) {
76				return NewAuthenticatedAPIClient(ctx, insecure)
77			},
78			coreClient:  coreapi.New,
79			openURL:     openBrowser,
80			githubAdmin: configureGitHubAdmin,
81			now:         time.Now,
82		}
83	}
84	
85	// runConfigureOnboarding is a seam for command tests. Bare interactive
86	// `entire configure` is the new end-to-end entry point; flag-based configure
87	// remains the non-interactive settings editor.
88	var runConfigureOnboarding = func(cmd *cobra.Command, opts EnableOptions) error {
89		return runConfigureOnboardingFlow(cmd, opts, newConfigureFlowDeps(false))
90	}
91	
92	func runConfigureOnboardingFlow(cmd *cobra.Command, opts EnableOptions, deps configureFlowDeps) error {
93		cmd.SilenceUsage = true
94		ctx := cmd.Context()
95		outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
96	
97		repoRoot, err := paths.WorktreeRoot(ctx)
98		if err != nil {
99			fmt.Fprintln(errW, "Not a git repository. Please run 'entire configure' from within a git repository.")
100			return NewSilentError(errors.New("not a git repository"))
101		}
102		owner, repo, cleanRemote, err := configureRepoIdentity(ctx)
103		if err != nil {
104			return err
105		}
106	
107		profile, err := ensureConfigureLogin(ctx, outW, errW, deps)
108		if err != nil {
109			return err
110		}
111	
112		reporter, err := deps.accessClient(ctx)
113		if err != nil {
114			return fmt.Errorf("connect to Entire: %w", err)
115		}
116		access, err := reporter.ReportEnable(ctx, cleanRemote)
117		if err != nil {
118			return fmt.Errorf("check repository access: %w", err)
119		}
120		if !access.Connected {
121			if err := ensureConfigureRepoAccess(ctx, outW, errW, reporter, access, cleanRemote, owner, repo, deps); err != nil {
122				return err
123			}
124		}
125	
126		client, err := deps.coreClient()
127		if err != nil {
128			return fmt.Errorf("connect to Entire control plane: %w", err)
129		}
130		placements, err := resolvePullablePlacements(ctx, client, owner, repo)
131		if err != nil {
132			return renderCoreError(err)
133		}
134		if len(placements) == 0 {
135			placements, err = configureCreateMirrors(ctx, outW, errW, client, owner, repo, profile.Jurisdiction)
136			if err != nil {
137				return err
138			}
139		}
140		if len(placements) == 0 {
141			return errors.New("no usable mirror was selected")
142		}
143	
144		manageRegionsHint := ""
145		if admin, adminErr := deps.githubAdmin(ctx, owner, repo); adminErr == nil && admin {
146			manageRegionsHint = fmt.Sprintf("Manage regions: entire repo mirror create · or %s/gh/%s/%s/settings",
147				configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
148		}
149		chosen, selectedAgents, err := promptConfigureUpstreamAndAgents(
150			ctx, errW, repoRoot, placements, profile.Jurisdiction, manageRegionsHint,
151		)
152		if err != nil {
153			return err
154		}
155		if err := configureUseMirror(ctx, repoRoot, owner, repo, chosen); err != nil {
156			return err
157		}
158	
159		before, err := configureGitChanges(ctx, repoRoot)
160		if err != nil {
161			return err
162		}
163	
164		// The combined form above owns both independent choices. Keeping them in a
165		// single group leaves the upstream visible while agents are focused and lets
166		// the user move back to it before submitting. runEnableInteractive applies
167		// the complete agent selection, writes settings, and installs hooks.
168	
169		opts.Yes = true
170		opts.UseProjectSettings = true
171		opts.UseLocalSettings = false
172		opts.SuppressDoneMessage = true
173		opts.SuppressAdditionalSetup = true
174		if err := runEnableInteractive(ctx, outW, selectedAgents, opts); err != nil {
175			return err
176		}
177		// A local enabled:false override must not win over the newly written project
178		// configuration. setEnabledFlag updates the project and synchronizes an
179		// existing local override without replacing its other local-only fields.
180		if err := setEnabledFlag(ctx, true, true); err != nil {
181			return err
182		}
183	
184		after, err := configureGitChanges(ctx, repoRoot)
185		if err != nil {
186			return err
187		}
188		generated := newConfigureChanges(before, after)
189		fmt.Fprintf(outW, "✓ Wrote %s\n", configDisplayProject)
190	
191		if err := configureSaveAndPush(cmd, repoRoot, owner, repo, before, generated, deps.now); err != nil {
192			return err
193		}
194		fmt.Fprintln(outW, "✓ Configuration complete")
195		fmt.Fprintln(outW)
196		fmt.Fprintln(outW, "  You're set. Start a session with any selected agent —")
197		fmt.Fprintf(outW, "  checkpoints will show up on %s/gh/%s/%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
198		return nil
199	}
200	
201	func configureWebBaseURL() string {
202		return strings.TrimRight(api.BaseURL(), "/")
203	}
204	
205	func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
206		raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
207		if err != nil {
208			return "", "", "", fmt.Errorf("read origin remote: %w", err)
209		}
210		info, err := gitremote.ParseURL(raw)
211		if err != nil {
212			return "", "", "", fmt.Errorf("parse origin remote: %w", err)
213		}
214		if info.Forge != mirrorUseForge {
215			return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
216		}
217		clean, err := cleanRemoteURLForReport(raw)
218		if err != nil {
219			return "", "", "", err
220		}
221		return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
222	}
223	
224	func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
225		target, err := deps.resolveAuth(ctx)
226		if err != nil {
227			return nil, err
228		}
229		if target.token != "" {
230			if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
231				return profile, nil
232			} else if !isKeychainTokenRejected(profileErr) {
233				return nil, fmt.Errorf("validate login: %w", profileErr)
234			}
235		}
236	
237		if err := deps.runLogin(ctx, outW, errW); err != nil {
238			return nil, fmt.Errorf("login: %w", err)
239		}
240		target, err = deps.resolveAuth(ctx)
241		if err != nil {
242			return nil, err
243		}
244		if target.token == "" {
245			return nil, errors.New("login completed without an active session")
246		}
247		profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
248		if err != nil {
249			return nil, fmt.Errorf("validate login: %w", err)
250		}
251		fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
252		return profile, nil
253	}
254	
255	func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, deps configureFlowDeps) error {
256		fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
257		installURL := strings.TrimSpace(initial.InstallURL)
258		if installURL == "" {
259			installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
260		}
261	
262		admin, adminErr := deps.githubAdmin(ctx, owner, repo)
263		if adminErr != nil || !admin {
264			fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
265			fmt.Fprintln(errW, "  Send them this link to continue:")
266			fmt.Fprintf(errW, "\n  %s\n", installURL)
267			return NewSilentError(errors.New("GitHub app installation required"))
268		}
269	
270		fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
271		fmt.Fprintf(outW, "  %s\n\n", installURL)
272		if err := deps.openURL(ctx, installURL); err != nil {
273			fmt.Fprintln(outW, "  Open the link above in your browser.")
274		}
275		stop := startSpinner(errW, "Waiting for installation")
276		stopped := false
277		defer func() {
278			if !stopped {
279				stop(false)
280			}
281		}()
282	
283		waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
284		defer cancel()
285		ticker := time.NewTicker(configureAccessPollInterval)
286		defer ticker.Stop()
287		for {
288			select {
289			case <-waitCtx.Done():
290				return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
291			case <-ticker.C:
292				access, err := reporter.ReportEnable(waitCtx, cleanRemote)
293				if err == nil && access.Connected {
294					stop(true)
295					stopped = true
296					fmt.Fprintln(outW, "✓ Access granted")
297					return nil
298				}
299			}
300		}
301	}
302	
303	func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
304		out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo, "--jq", ".permissions.admin").Output()
305		if err != nil {
306			return false, fmt.Errorf("check GitHub admin permission: %w", err)
307		}
308		admin, err := strconv.ParseBool(strings.TrimSpace(string(out)))
309		if err != nil {
310			return false, fmt.Errorf("parse GitHub admin permission: %w", err)
311		}
312		return admin, nil
313	}
314	
315	func configureCreateMirrors(ctx context.Context, outW, errW io.Writer, client *coreapi.Client, owner, repo, jurisdiction string) ([]coreapi.ResolvedPlacement, error) {
316		regions, err := availableRegions(ctx, client)
317		if err != nil {
318			return nil, fmt.Errorf("list regions: %w", err)
319		}
320		if len(regions) == 0 {
321			return nil, errors.New("no regions available to mirror into")
322		}
323		selected, err := pickConfigureRegions(ctx, outW, regions, jurisdiction)
324		if err != nil {
325			return nil, err
326		}
327		results := createMirrors(ctx, errW, mirrorTargets([]coreapi.AvailableMirror{{Owner: owner, Repo: repo}}, selected), false, 30*time.Minute)
328		if err := reportMirrorResults(outW, errW, results); err != nil {
329			return nil, err
330		}
331		placements := make([]coreapi.ResolvedPlacement, 0, len(results))
332		for i, result := range results {
333			if result.err != nil || result.cloneURL == "" {
334				continue
335			}
336			region := selected[i]
337			placements = append(placements, coreapi.ResolvedPlacement{
338				ClusterHost:  region.host,
339				Cell:         coreapi.NewOptString(region.slug),
340				Jurisdiction: coreapi.NewOptString(region.jurisdiction),
341			})
342		}
343		return placements, nil
344	}
345	
346	func pickConfigureRegions(ctx context.Context, outW io.Writer, regions []regionChoice, jurisdiction string) ([]regionChoice, error) {
347		opts, defaults := clusterChoices(regions, jurisdiction)
348		byHost := make(map[string]regionChoice, len(regions))
349		for _, region := range regions {
350			byHost[region.host] = region
351		}
352		selected := append([]string(nil), defaults...)
353		form := NewAccessibleForm(huh.NewGroup(
354			huh.NewMultiSelect[string]().
355				Title("Which regions should this repository live in?").
356				Description("Space to select, enter to confirm — your data stays in the selected regions.").
357				Options(opts...).
358				Height(multiSelectHeight(len(opts))).
359				Validate(func(values []string) error {
360					if len(values) == 0 {
361						return errors.New("select at least one region")
362					}
363					return nil
364				}).
365				Value(&selected),
366		))
367		if err := form.RunWithContext(ctx); err != nil {
368			if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
369				return nil, cancelErr
370			}
371			return nil, NewSilentError(errors.New("configure cancelled"))
372		}
373		chosen := make([]regionChoice, 0, len(selected))
374		for _, host := range selected {
375			if region, ok := byHost[host]; ok {
376				chosen = append(chosen, region)
377			}
378		}
379		return chosen, nil
380	}
381	
382	// configureFocusChangedMsg forces huh's dynamic titles to re-evaluate after a
383	// field transition. huh evaluates TitleFunc before it calls Blur/Focus while
384	// handling NextField, so without this follow-up frame the help bar changes but
385	// the old section keeps the active-colored question mark until another keypress.
386	type configureFocusChangedMsg struct{}
387	
388	func configureRefreshFocus() tea.Cmd {
389		return func() tea.Msg { return configureFocusChangedMsg{} }
390	}
391	
392	type configureUpstreamField struct {
393		*huh.Select[string]
394	
395		value       *string
