565	// promptConfigureUpstreamAndAgents presents upstream and agents as one
566	// persistent form. Arrow keys stay within the active section; Enter confirms a
567	// section and advances, while shift+tab revisits the previous section.
568	func promptConfigureUpstreamAndAgents(ctx context.Context, errW io.Writer, repoRoot string, placements []coreapi.ResolvedPlacement, jurisdiction, manageRegionsHint string) (coreapi.ResolvedPlacement, []agent.Agent, error) {
569		currentHost := configureCurrentUpstream(ctx, repoRoot)
570		placements = configurePlacementOrder(placements, currentHost, jurisdiction)
571		if len(placements) == 0 {
572			return coreapi.ResolvedPlacement{}, nil, errors.New("no upstreams available")
573		}
574	
575		// configurePlacementOrder puts the configured upstream first, so it is also
576		// the initial selection. If this repo has no Entire upstream yet, it falls
577		// back to the jurisdiction-preferred placement.
578		selectedHost := placements[0].ClusterHost
579		placementByHost := make(map[string]coreapi.ResolvedPlacement, len(placements))
580		for _, placement := range placements {
581			placementByHost[placement.ClusterHost] = placement
582		}
583		upstreamOptions := func() []huh.Option[string] {
584			return configureUpstreamOptions(placements, selectedHost, currentHost)
585		}
586	
587		external.DiscoverAndRegisterAlways(ctx)
588		preselected := configureAgentPreselection(ctx)
589		agentOptions := configureAgentOptions(hookAgentOptions(preselected), preselected)
590		if len(agentOptions) == 0 {
591			return coreapi.ResolvedPlacement{}, nil, errors.New("no agents with hook support available")
592		}
593		selectedAgentNames := make([]string, 0, len(preselected))
594		for _, option := range agentOptions {
595			if _, ok := preselected[types.AgentName(option.Value)]; ok {
596				selectedAgentNames = append(selectedAgentNames, option.Value)
597			}
598		}
599	
600		// huh's footer already documents navigation. Keep field descriptions for
601		// contextual information only, rather than repeating keyboard controls.
602		upstreamDescription := manageRegionsHint
603		upstreamControl := &configureUpstreamField{
604			value:       &selectedHost,
605			committed:   selectedHost,
606			highlighted: selectedHost,
607		}
608		upstreamControl.Select = huh.NewSelect[string]().
609			TitleFunc(func() string {
610				return configureQuestionTitle("Which upstream do you want to use?", upstreamControl.focused)
611			}, &upstreamControl.focused).
612			Description(upstreamDescription).
613			Options(upstreamOptions()...).
614			Height(configureFieldHeight(len(placements), upstreamDescription)).
615			Value(&selectedHost)
616		upstreamControl.refresh = func() {
617			upstreamControl.Select.Options(upstreamOptions()...)
618		}
619	
620		agentControl := &configureAgentField{}
621		agentControl.MultiSelect = huh.NewMultiSelect[string]().
622			TitleFunc(func() string {
623				return configureQuestionTitle("Select the agents you want to use", agentControl.focused)
624			}, &agentControl.focused).
625			Options(agentOptions...).
626			// MultiSelect subtracts its title from an implicit viewport height, so
627			// include exactly one title row to show every option without padding.
628			Height(len(agentOptions) + 1).
629			Validate(func(values []string) error {
630				if len(values) == 0 {
631					return errors.New("select at least one agent")
632				}
633				return nil
634			}).
635			Value(&selectedAgentNames)
636	
637		group := huh.NewGroup(upstreamControl, agentControl)
638		form := newConfigureForm(group)
639		// Separate the form from the shell prompt or preceding onboarding status.
640		fmt.Fprintln(errW)
641		if err := form.RunWithContext(ctx); err != nil {
642			if cancelErr := handleFormCancellation(errW, "Configure", err); cancelErr != nil {
643				return coreapi.ResolvedPlacement{}, nil, cancelErr
644			}
645			return coreapi.ResolvedPlacement{}, nil, NewSilentError(errors.New("configure cancelled"))
646		}
647	
648		chosen, ok := placementByHost[selectedHost]
649		if !ok {
650			return coreapi.ResolvedPlacement{}, nil, errors.New("selected upstream is no longer available")
651		}
652		selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
653		for _, name := range selectedAgentNames {
654			ag, err := agent.Get(types.AgentName(name))
655			if err != nil {
656				return coreapi.ResolvedPlacement{}, nil, fmt.Errorf("load selected agent %q: %w", name, err)
657			}
658			selectedAgents = append(selectedAgents, ag)
659		}
660		return chosen, selectedAgents, nil
661	}
