848	func configurePlacementOrder(placements []coreapi.ResolvedPlacement, currentHost, jurisdiction string) []coreapi.ResolvedPlacement {
849		ordered := append([]coreapi.ResolvedPlacement(nil), placements...)
850		sort.SliceStable(ordered, func(i, j int) bool {
851			iCurrent := strings.EqualFold(ordered[i].ClusterHost, currentHost)
852			jCurrent := strings.EqualFold(ordered[j].ClusterHost, currentHost)
853			if iCurrent != jCurrent {
854				return iCurrent
855			}
856			iHome := strings.EqualFold(ordered[i].Jurisdiction.Or(""), jurisdiction)
857			jHome := strings.EqualFold(ordered[j].Jurisdiction.Or(""), jurisdiction)
858			if currentHost == "" && iHome != jHome {
859				return iHome
860			}
861			return configurePlacementLabel(ordered[i]) < configurePlacementLabel(ordered[j])
862		})
863		return ordered
864	}
