892	func configureUseMirror(ctx context.Context, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) error {
893		remotes, err := listGitRemotes(ctx, repoRoot)
894		if err != nil {
895			return err
896		}
897		current := ""
898		if remotes[defaultMirrorRemote] {
899			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
900			if err != nil {
901				return fmt.Errorf("read origin remote URL: %w", err)
902			}
903		}
904		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
905		preserve := defaultMirrorUpstreamRemote
906		// An existing forge alias already preserves direct GitHub access. Avoid
907		// manufacturing another alias, and never preserve an old Entire placement
908		// under the misleading name "upstream".
909		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol == gitremote.ProtocolEntire {
910			preserve = ""
911		}
912		plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
913		return applyMirrorRemotePlan(ctx, repoRoot, plan)
914	}
