916	// configureGitChanges returns porcelain status keyed by path. Its values retain
917	// XY so callers can detect whether anything was already staged before the flow.
918	func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
919		out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
920		if err != nil {
921			return nil, fmt.Errorf("read git status: %w", err)
922		}
923		changes := make(map[string]string)
924		for _, line := range strings.Split(out, "\n") {
925			if len(line) < 4 {
926				continue
927			}
928			path := strings.TrimSpace(line[3:])
929			if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
930				path = path[arrow+4:]
931			}
932			if path != "" {
933				changes[path] = line[:2]
934			}
935		}
936		return changes, nil
937	}
