939	func newConfigureChanges(before, after map[string]string) []string {
940		paths := make([]string, 0, len(after))
941		for path := range after {
942			if _, existed := before[path]; !existed {
943				paths = append(paths, path)
944			}
945		}
946		sort.Strings(paths)
947		return paths
948	}
