950	func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, now func() time.Time) error {
951		outW := cmd.OutOrStdout()
952		if len(generated) == 0 {
953			fmt.Fprintln(outW, "  No new configuration changes to commit.")
954			return nil
955		}
956		if len(before) != 0 {
957			fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
958			fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
959			return nil
960		}
961	
962		branch, err := gitRunner(cmd.Context(), repoRoot, "branch", "--show-current")
963		if err != nil || branch == "" {
964			return errors.New("cannot save configuration from a detached HEAD")
965		}
966		protected, protectionErr := configureBranchProtected(cmd.Context(), owner, repo, branch)
967		if protectionErr != nil {
968			// Protection discovery is advisory; a rejected direct push still fails
969			// safely at git push.
970			protected = false
971		}
972		choice, err := promptConfigureSave(cmd.Context(), cmd.ErrOrStderr(), branch, protected)
973		if err != nil {
974			return err
975		}
976		if protected && choice == configureSaveDirect {
977			return fmt.Errorf("%s is protected; push to a new branch", branch)
978		}
979		if choice != configureSaveDirect && choice != configureSaveNewBranch {
980			return fmt.Errorf("unknown save choice %q", choice)
981		}
982	
983		pushBranch := branch
984		if choice == configureSaveNewBranch {
985			var err error
986			pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, now)
987			if err != nil {
988				return err
989			}
990			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
991				return fmt.Errorf("create configuration branch: %w", err)
992			}
993		}
994	
995		args := []string{"add", "--"}
996		args = append(args, generated...)
997		if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
998			return fmt.Errorf("stage configuration: %w", err)
999		}
1000		if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1001			return fmt.Errorf("commit configuration: %w", err)
1002		}
1003		sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1004		if err != nil {
1005			return fmt.Errorf("read configuration commit: %w", err)
1006		}
1007		fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1008		if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", defaultMirrorRemote, pushBranch); err != nil {
1009			return fmt.Errorf("push configuration: %w", err)
1010		}
1011		fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", defaultMirrorRemote, pushBranch)
1012		if choice == configureSaveNewBranch {
1013			fmt.Fprintln(outW, "  Open a trail to merge it:")
1014			fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1015		}
1016		return nil
1017	}
1018	
1019	func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1020		out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/branches/"+url.PathEscape(branch), "--jq", ".protected").Output()
1021		if err != nil {
1022			return false, fmt.Errorf("check GitHub branch protection: %w", err)
1023		}
1024		protected, err := strconv.ParseBool(strings.TrimSpace(string(out)))
1025		if err != nil {
1026			return false, fmt.Errorf("parse GitHub branch protection: %w", err)
1027		}
1028		return protected, nil
1029	}
1030	
1031	func availableConfigureBranch(ctx context.Context, repoRoot string, now func() time.Time) (string, error) {
1032		candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1033		for _, candidate := range candidates {
1034			_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+candidate)
1035			if err == nil {
1036				continue // branch already exists
1037			}
1038			var exitErr *exec.ExitError
1039			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1040				return candidate, nil // show-ref uses 1 for a missing ref
1041			}
1042			return "", fmt.Errorf("check configuration branch %q: %w", candidate, err)
1043		}
1044		return "", errors.New("could not choose an unused configuration branch name")
1045	}
